Use ASP.NET Core's **`WebApplicationFactory<T>`** — it hosts your app in-memory with a test `HttpClient`, no real port needed.

```csharp
// MyMcpServerTests.cs
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using System.Text.Json;

public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.Equal(1, body.GetProperty("id").GetInt32());
        Assert.True(body.GetProperty("result").TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        // Initialize first
        await InitializeSession();

        var request = new { jsonrpc = "2.0", id = 2, method = "tools/list" };
        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }

    private async Task InitializeSession() { /* send initialize as above */ }
}
```

**Key points:**

1. **`WebApplicationFactory<Program>`** boots your entire middleware pipeline (auth, routing, MCP handling) in-process — no ports, no process management.
2. **Override services** for isolation (e.g., swap a real DB for an in-memory one):
   ```csharp
   factory.WithWebHostBuilder(builder =>
       builder.ConfigureServices(services =>
           services.AddSingleton<IMyDep, FakeDep>()));
   ```
3. **For SSE transport**, use `factory.CreateDefaultClient()` and read the SSE stream manually with `HttpCompletionOption.ResponseHeadersRead`.
4. **For Streamable HTTP** (bidirectional), post JSON-RPC to the MCP endpoint and assert on the response body or SSE events.

Add the `Microsoft.AspNetCore.Mvc.Testing` NuGet package and ensure your server project exposes a `Program` class (top-level statements do this automatically in .NET 6+).
